  'Titel van de presentatie': 'Názov prezentácie',
  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · SQL injection v prihlasovacom formulári',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'Odoslať tento obrázok do modelu AI?',
  'De afbeelding gaat ongewijzigd naar': 'Obrázok bude bez zmeny odoslaný na',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck v obrázku nič nezačierňuje: tváre, text na snímke obrazovky a viditeľné údaje odídu s ním.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Kontrola obrázkov tu našla jednu alebo viac rozpoznateľných tvárí.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Vedľa exportu vzniknú dva súbory, pomocou ktorých si príjemca môže začiernenia overiť.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'vypisuje, čo bolo vynechané, bez samotných hodnôt. Tento súbor môže ísť so správou.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'obsahuje kľúče, ktorými možno každú začiernenú hodnotu spätne dopočítať. Tento súbor neposielajte: začiernenie by sa tým zrušilo. Uchovajte ho pri zdroji.',
  'slides': 'snímky',
  'Achtergehouden': 'Zadržané',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Zadržané: klasifikované prísnejšie než prezentácia',
  '1 slide achtergehouden door haar TLP': '1 snímka zadržaná kvôli svojmu TLP',
  'slides achtergehouden door hun TLP': 'snímok zadržaných kvôli ich TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Tieto snímky sa nedostanú do prezentácie, exportu ani balíka. Zvýšte úroveň TLP prezentácie v Informáciách o prezentácii, aby sa zahrnuli.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Všetky snímky sú zadržané kvôli svojej klasifikácii TLP — nie je čo zobraziť.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Všetky snímky sú zadržané kvôli svojej klasifikácii TLP — nie je čo exportovať.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Všetky snímky sú preskočené alebo zadržané kvôli svojej klasifikácii TLP — nie je čo zobraziť.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Všetky snímky sú preskočené alebo zadržané kvôli svojej klasifikácii TLP — nie je čo exportovať.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Čísla grafov sa neuložili — existujú už len v tomto okne:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'V prehliadači neexistuje obnova po páde: ak zavriete túto kartu, neuložená práca je preč. Uložte si prezentáciu sami.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Lokálna databáza CVE (sťahovanie spúšťate sami): OciDeck načítava hromadné údaje cez api.github.com a súbor vydania, na ktorý táto adresa odkazuje.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Vyhľadávanie CVE (predvolene vypnuté): keď je zapnuté, váš hľadaný výraz ide na nastavené zrkadlo CVE, a ak tam nič nenájde, do európskej databázy ENISA a do MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Vložené video z YouTube alebo Vimea načíta prehrávač od tejto služby.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  V prehliadači: ak prehliadač odmietne načítať adresu priamo, OciDeck to skúsi znova cez server, z ktorého aplikácia prišla; tá adresa sa potom dostane na onen server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Odvolanie sa neuložilo. Pri ďalšom spustení bude váš súhlas opäť platiť.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Nadpis sekcie, ktorý ohlasuje novú časť prezentácie. Buďte struční. Pridajte obrázok na pozadie z knižnice obrázkov.',
  'Bronnen doorzoeken…': 'Prehľadávanie zdrojov…',
  'Niet doorzocht': 'Neprehľadané',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Táto kontrola sa vo webovej verzii nespúšťa: rozpoznávanie tvárí vyžaduje systémovú knižnicu, ktorú prehliadač nemá. Na kontrolu tvárí v obrázkoch použite desktopovú verziu.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Token potrebuje práva na čítanie a zápis do repozitára. Gitea a Forgejo nemajú vyhľadávanie na serveri; OciDeck hľadá lokálne.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Token potrebuje rozsah repo (alebo podrobne: Contents na čítanie a zápis).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Token potrebuje read_repository, write_repository a read_api. Vyhľadávanie na serveri vyžaduje Advanced alebo Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Rýchle hľadanie na serveri — pre oneskorenie indexovania môže chýbať práve zmenená sada.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Médiá sa v obyčajnom súbore .md nezachovajú',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Obrázky, video a zvuk, ktoré ste vybrali na tejto karte, existujú len v pamäti. Obyčajný súbor .md ich neuchová — po opätovnom otvorení budú preč. Exportujte ako balík .ocideck, aby ste si médiá vzali so sebou.',
  'Media verwijderd om privacyredenen':
      'Médiá odstránené z dôvodu ochrany súkromia',
